package com.bank.budget;

// Budget derived from SLO over a request window: allowed failures.
public class ErrorBudget {
    private final double sloPercent;       // e.g. 99.9
    private final long totalRequests;      // requests in the window

    public ErrorBudget(double sloPercent, long totalRequests) {
        this.sloPercent = sloPercent;
        this.totalRequests = totalRequests;
    }

    // Allowed failures = (100 - SLO)/100 * total requests.
    public long allowedFailures() {
        return Math.round((100.0 - sloPercent) / 100.0 * totalRequests);
    }

    public double sloPercent() { return sloPercent; }
    public long totalRequests() { return totalRequests; }
}
