package com.bank.budget;

import java.util.logging.Logger;

public class BudgetTracker {
    private static final Logger log = Logger.getLogger(BudgetTracker.class.getName());
    private final ErrorBudget budget;
    private long failuresConsumed = 0;

    public BudgetTracker(ErrorBudget budget) { this.budget = budget; }

    // Record failures observed in some interval; log consumption + burn.
    public void recordFailures(long failures, String interval) {
        failuresConsumed += failures;
        long allowed = budget.allowedFailures();
        double consumedPct = allowed == 0 ? 100 : (failuresConsumed * 100.0 / allowed);
        log.info(() -> String.format("%s: +%d failures → consumed %d/%d budget (%.1f%%)",
            interval, failures, failuresConsumed, allowed, consumedPct));
        // Burn rate: this interval's failures vs the whole budget.
        double burnRate = allowed == 0 ? 0 : (failures * 1.0 / allowed);
        if (burnRate > 0.5) {
            log.severe(() -> String.format("FAST BURN: %.0f%% of monthly budget in one "
                + "interval — PAGE on-call now!", burnRate * 100));
        }
    }

    public double remainingPercent() {
        long allowed = budget.allowedFailures();
        if (allowed == 0) return 0;
        return Math.max(0, (allowed - failuresConsumed) * 100.0 / allowed);
    }

    public boolean isExhausted() { return failuresConsumed >= budget.allowedFailures(); }
}
