package com.bank.budget;

import java.util.logging.Logger;

public class ReleasePolicy {
    private static final Logger log = Logger.getLogger(ReleasePolicy.class.getName());

    // Error-budget policy: ship while budget remains, freeze when spent.
    public boolean canShipFeature(BudgetTracker tracker) {
        double remaining = tracker.remainingPercent();
        if (tracker.isExhausted()) {
            log.severe(() -> "BUDGET SPENT (0% left) → FEATURE FREEZE: only reliability fixes "
                + "and critical security patches may ship.");
            return false;
        }
        if (remaining < 25) {
            log.warning(() -> String.format("Budget low (%.1f%% left) → ship only low-risk "
                + "changes, tighten canary analysis.", remaining));
            return true;
        }
        log.info(() -> String.format("Budget healthy (%.1f%% left) → OK to ship features "
            + "and take reasonable deploy risk.", remaining));
        return true;
    }
}
