package com.bank.budget;

import java.util.logging.*;

public class ErrorBudgetDemo {
    private static final Logger log = Logger.getLogger(ErrorBudgetDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // SLO 99.9% over 1,000,000 monthly transfer requests → 1000 allowed failures.
        ErrorBudget budget = new ErrorBudget(99.9, 1_000_000);
        BudgetTracker tracker = new BudgetTracker(budget);
        ReleasePolicy policy = new ReleasePolicy();

        log.info(() -> "Monthly error budget = " + budget.allowedFailures()
            + " allowed failures (SLO " + budget.sloPercent() + "%)");

        log.info("=== Week 1: normal failures ===");
        tracker.recordFailures(200, "Week 1");
        policy.canShipFeature(tracker);

        log.info("=== Week 2: a bad deploy burns budget fast ===");
        tracker.recordFailures(600, "Week 2 (incident)");   // fast burn
        policy.canShipFeature(tracker);

        log.info("=== Week 3: more failures exhaust the budget ===");
        tracker.recordFailures(300, "Week 3");
        policy.canShipFeature(tracker);                      // now frozen
    }
}
